/**
 * Errors crossing the FFI boundary. Each maps 1:1 to a `dpay_core` failure so the app can react
 * (bad key length, malformed QR, a rejected authorization) without string-sniffing.
 */
sealed class DpayException: kotlin.Exception() {
    
    class BadSecretLength(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class BadPubkeyLength(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class BadNonceLength(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class BadBase64(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class BadWireLength(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class PubkeyMismatch(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class BadInput(
        
        val v1: kotlin.String
        ) : DpayException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * A decimal amount string was rejected by `parse_amount`. Carries a debuggable code matching
     * `dpay_core::AmountError` (`empty`/`not_a_number`/`negative`/`too_many_decimals`/`overflow`)
     * so the app reacts without string-sniffing. MC1 unit 1.
     */
    class Amount(
        
        val v1: kotlin.String
        ) : DpayException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NfcWrongState(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class NfcNotDpay(
        ) : DpayException() {
        override val message
            get() = ""
    }
    
    class NfcProtocol(
        ) : DpayException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DpayException> {
        override fun lift(error_buf: RustBuffer.ByValue): DpayException = FfiConverterTypeDpayError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDpayError : FfiConverterRustBuffer<DpayException> {
    override fun read(buf: ByteBuffer): DpayException {
        

        return when(buf.getInt()) {
            1 -> DpayException.BadSecretLength()
            2 -> DpayException.BadPubkeyLength()
            3 -> DpayException.BadNonceLength()
            4 -> DpayException.BadBase64()
            5 -> DpayException.BadWireLength()
            6 -> DpayException.PubkeyMismatch()
            7 -> DpayException.BadInput(
                FfiConverterString.read(buf),
                )
            8 -> DpayException.Amount(
                FfiConverterString.read(buf),
                )
            9 -> DpayException.NfcWrongState()
            10 -> DpayException.NfcNotDpay()
            11 -> DpayException.NfcProtocol()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DpayException): ULong {
        return when(value) {
            is DpayException.BadSecretLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.BadPubkeyLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.BadNonceLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.BadBase64 -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.BadWireLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.PubkeyMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.BadInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is DpayException.Amount -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is DpayException.NfcWrongState -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.NfcNotDpay -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DpayException.NfcProtocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: DpayException, buf: ByteBuffer) {
        when(value) {
            is DpayException.BadSecretLength -> {
                buf.putInt(1)
                Unit
            }
            is DpayException.BadPubkeyLength -> {
                buf.putInt(2)
                Unit
            }
            is DpayException.BadNonceLength -> {
                buf.putInt(3)
                Unit
            }
            is DpayException.BadBase64 -> {
                buf.putInt(4)
                Unit
            }
            is DpayException.BadWireLength -> {
                buf.putInt(5)
                Unit
            }
            is DpayException.PubkeyMismatch -> {
                buf.putInt(6)
                Unit
            }
            is DpayException.BadInput -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is DpayException.Amount -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is DpayException.NfcWrongState -> {
                buf.putInt(9)
                Unit
            }
            is DpayException.NfcNotDpay -> {
                buf.putInt(10)
                Unit
            }
            is DpayException.NfcProtocol -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Lifecycle phase of a tap, for a live UI status indicator. Mirrors [`dpay_core::nfc::SessionPhase`]
 * (lifecycle only — failures surface as thrown `DpayError`s / a platform tag-loss, never as a
 * phase). The app renders a spinner on `Linking`/`Exchanging`, a review prompt on
 * `AwaitingApproval`, and a terminal mark on `Complete` / `Declined`.
 */

enum class NfcPhase {
    
    IDLE,
    LINKING,
    EXCHANGING,
    AWAITING_APPROVAL,
    /**
     * The wire was transferred; the merchant is settling online and the payer awaits the receipt.
     */
    SETTLING,
    COMPLETE,
    DECLINED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeNfcPhase: FfiConverterRustBuffer<NfcPhase> {
    override fun read(buf: ByteBuffer) = try {
        NfcPhase.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: NfcPhase) = 4UL

    override fun write(value: NfcPhase, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * What the merchant reader should do after feeding a card response — a flat enum (no associated
 * data) so it maps cleanly to every target language. When `Done`, pull the wire via
 * [`FfiReaderConductor::wire`].
 */

enum class NfcStep {
    
    /**
     * Send the next command from `next_command`.
     */
    CONTINUE,
    /**
     * The payer is still deciding — keep polling / re-tap (`next_command` re-SELECTs).
     */
    PENDING,
    /**
     * The signed wire is ready; fetch it with `wire()`, then verify + submit online. Afterwards
     * call `provideReceipt` to hand the outcome back to the payer over the same tap.
     */
    DONE,
    /**
     * The settlement receipt was delivered to the payer — the tap is fully complete.
     */
    CONFIRMED,
    /**
     * The payer declined; abandon the sale.
     */
    DECLINED,
    /**
     * The card answered NOT_READY at SELECT: a dpay card is routed but no payer session is armed
     * (the payer isn't in Pay mode). Keep polling / re-SELECT via `next_command`, or surface an
     * actionable message and stop.
     */
    WAITING_FOR_PAYER;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeNfcStep: FfiConverterRustBuffer<NfcStep> {
    override fun read(buf: ByteBuffer) = try {
        NfcStep.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: NfcStep) = 4UL

    override fun write(value: NfcStep, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
